# Step 04: simple BFS without extra imports
start, end = 18031, 56431
# build edges in window
edges = [e for e in events if start <= e[2] <= end]
# adjacency
adj = {}
for u,v,t in edges:
    adj.setdefault(u, []).append((t,v))
for u in adj:
    adj[u].sort()
# starting frontier: all outgoing from 1006
frontier = []
for u,v,t in edges:
    if u==1006:
        frontier.append((v,t, [(1006,t,'start'), (v,t)]))
# BFS
visited = set((v,t) for (v,t,_) in frontier)
found_path = None
while frontier:
    node, curt, path = frontier.pop(0)
    if node==1860:
        found_path = path
        break
    if node not in adj: continue
    lst = adj[node]
    # find next events with time > curt and <= curt+600
    for t2,v2 in lst:
        if t2>curt and t2-curt<=600:
            state = (v2,t2)
            if state not in visited:
                visited.add(state)
                frontier.append((v2,t2, path+[(v2,t2)]))

print('found_path_exists:', found_path is not None)
if found_path:
    print('path:')
    for p in found_path:
        print(p)

# print all events involving 1006 or 1860 for reference
print('\nrelevant events:')
for e in edges:
    if e[0] in {1006,1860} or e[1] in {1006,1860}:
        print(e)

# Step 05: print events at the times on the candidate path
times = [36803, 37039, 37196, 37431, 37659]
res = []
for e in events:
    if e[2] in times:
        res.append(e)
print('matches:')
for r in res:
    print(r)
# Also print surrounding events around those times +-1 to ensure uniqueness
print('\nSurrounding events:')
for t in times:
    for e in events:
        if t-1 <= e[2] <= t+1:
            print(e)
